/** Controls that get evidence attached. The remaining three stay uncovered so the coverage tile is not a flat 100%. */
const EVIDENCED_CONTROLS = ['CC1.1', 'CC2.1', 'CC5.1', 'CC6.1', 'CC6.2', 'CC7.2', 'CC9.1'] as const

// ── teardown ────────────────────────────────────────────────────────────────

/**
 * The seed builds from clean rather than upserting, so a previous run has to go
 * first. That is only possible while the tenant has no audit history:
 * `audit_events.tenant_id` carries a foreign key to `organizations`, and the
 * table is append-only behind a Postgres trigger, so once the demo org has
 * written a single audit event it can no longer be deleted.
 *
 * That is the audit-immutability guarantee doing its job, not a bug. Re-seeding
 * therefore needs a fresh database:
 *
 *   node scripts/reset-local-db.mjs phiguard_demo
 */
async function resetDemoWorkspace(db: DB) {
  const [existing] = await db
    .select({ id: organizations.id })
    .from(organizations)
    .where(eq(organizations.slug, DEMO_ORG_SLUG))
    .limit(1)

  if (existing) {
    const [{ count: auditCount }] = await db
      .select({ count: count() })
      .from(auditEvents)
      .where(eq(auditEvents.tenantId, existing.id))

    if (auditCount > 0) {
      throw new Error(
        `The demo organization already exists and has ${auditCount} audit events, which are `
        + 'append-only and pin the tenant row in place. Recreate the database first:\n\n'
        + '  node scripts/reset-local-db.mjs phiguard_demo\n',
      )
    }

    // soc2_evidence.tenant_id has no foreign key, so it will not cascade.
    await db.delete(soc2Evidence).where(eq(soc2Evidence.tenantId, existing.id))
    await db.delete(organizations).where(eq(organizations.id, existing.id))
  }

  const emails = PEOPLE.map((person) => person.email)
  await db.delete(users).where(inArray(users.email, emails))
}

// ── build ───────────────────────────────────────────────────────────────────

async function createPeople(db: DB) {
  const people: (DemoPerson & { id: string })[] = []

  for (const definition of PEOPLE) {
    const name = `${faker.person.firstName()} ${faker.person.lastName()}`

    const [user] = await db
      .insert(users)
      .values({ email: definition.email, name, emailVerified: true, emailVerifiedAt: new Date() })
      .returning()

    await db.insert(accounts).values({
      userId: user.id,
      accountId: definition.email,
      providerId: 'credential',
      password: await hashPassword(DEMO_PASSWORD),
    })

    people.push({ ...definition, name, id: user.id })
  }

  return people
}

async function createOrganization(db: DB, ownerId: string) {
  const [organization] = await db
    .insert(organizations)
    .values({
      name: DEMO_ORG_NAME,
      slug: DEMO_ORG_SLUG,
      // Group unlocks the compliance program and SOC 2 surfaces, which is what
      // makes the demo worth screenshotting.
      plan: 'group',
      planStatus: 'active',
      maxMembers: 25,
      planSelectedAt: daysAgo(210),
      termsAcceptedAt: daysAgo(210),
      termsAcceptedByUserId: ownerId,
      baaSignedAt: daysAgo(210),
      baaSignedByUserId: ownerId,
    })
    .returning()

  return organization
}

async function acceptLegalDocuments(db: DB, tenantId: string, owner: DemoPerson & { id: string }) {
  await db.insert(legalAcceptances).values(
    getStandardLegalDocuments().map((document) => ({
      tenantId,
      documentType: document.type,
      documentVersion: document.version,
      documentTitle: document.title,
      contentHash: hashDocument(document),
      customerEntityName: DEMO_ORG_NAME,
      signerName: owner.name,
      signerTitle: owner.title,
      signerEmail: owner.email,
      acceptedByUserId: owner.id,
      acceptedAt: daysAgo(210),
      snapshot: document,
    })),
  )
}

async function createLocationsAndMemberships(
  db: DB,
  tenantId: string,
  people: (DemoPerson & { id: string })[],
) {
  const createdLocations = await db
    .insert(locations)
    .values(LOCATION_DEFINITIONS.map((location) => ({ ...location, organizationId: tenantId })))
    .returning()

  for (const person of people) {
    const [membership] = await db
      .insert(memberships)
      .values({ userId: person.id, tenantId, role: person.role, acceptedAt: daysAgo(180) })
      .returning()

    // Only location-scoped roles need grants; org-wide roles resolve every
    // active location without them.
    const needsGrants = person.role === 'location_manager' || person.role === 'location_staff'
    if (!needsGrants) continue

    await db.insert(locationGrants).values(
      person.locationIndexes.map((index) => ({
        tenantId,
        membershipId: membership.id,
        locationId: createdLocations[index].id,
      })),
    )
  }

  return createdLocations
}

async function seedTasks(
  db: DB,
  tenantId: string,
  locationIds: string[],
  byKey: Map<string, DemoPerson & { id: string }>,
) {
  const owner = byKey.get('owner')!
  let commentsAdded = 0

  for (const template of TASK_TEMPLATES) {
    const creator = byKey.get(template.assignee ?? 'owner') ?? owner

    const task = await createTask(db, {
      tenantId,
      locationId: locationIds[template.locationIndex],
      title: template.title,
      description: template.description,
      priority: template.priority,
      dueAt: daysFromNow(template.offsetDays),
      createdBy: creator.id,
    })

    if (template.assignee) {
      const assignee = byKey.get(template.assignee)!
      await assignTask(db, { taskId: task.id, tenantId, userId: assignee.id, assignedBy: owner.id })
    }

    // createTask always starts a task at 'open'; move it through the real
    // status mutation so the change lands in the audit log.
    if (template.status !== 'open') {
      await updateTaskStatus(db, { taskId: task.id, tenantId, actorId: creator.id, status: template.status })
    }

    if (template.status === 'blocked') {
      await addComment(db, {
        taskId: task.id,
        tenantId,
        authorId: creator.id,
        body: 'Blocked pending the vendor response. Will revisit once we have a date.',
      })
      commentsAdded += 1
    }
  }

  return { tasks: TASK_TEMPLATES.length, comments: commentsAdded }
}

async function seedChecklists(
  db: DB,
  tenantId: string,
  locationIds: string[],
  actorId: string,
) {
  await runSeed(db)

  await assignChecklistTemplateToLocations(db, {
    tenantId,
    templateId: STARTER_TEMPLATES.accessReview,
    locationIds,
    actorId,
    dueAt: daysFromNow(12),
  })
  await assignChecklistTemplateToLocations(db, {
    tenantId,
    templateId: STARTER_TEMPLATES.baaInventory,
    locationIds: [locationIds[0]],
    actorId,
    dueAt: daysFromNow(25),
  })
  await assignChecklistTemplateToLocations(db, {
    tenantId,
    templateId: STARTER_TEMPLATES.trainingLog,
    locationIds: [locationIds[0], locationIds[1]],
    actorId,
    dueAt: daysAgo(2),
  })

  // Partially complete the work so progress bars show real intermediate state
  // rather than 0% or 100% everywhere.
  const allChecklists = await db
    .select({ id: checklists.id })
    .from(checklists)
    .where(eq(checklists.tenantId, tenantId))

  let completed = 0
  for (const [index, checklist] of allChecklists.entries()) {
    const items = await db
      .select({ id: checklistItems.id })
      .from(checklistItems)
      .where(and(eq(checklistItems.checklistId, checklist.id), eq(checklistItems.tenantId, tenantId)))

    // Vary completion per checklist: none, some, or all.
    const target = [0, 1, 2, 3][index % 4]
    for (const item of items.slice(0, Math.min(target, items.length))) {
      await completeItem(db, { itemId: item.id, tenantId, actorId })
      completed += 1
    }
  }

  return { checklists: allChecklists.length, itemsCompleted: completed }
}

async function seedIncidents(
  db: DB,
  tenantId: string,
  locationIds: string[],
  byKey: Map<string, DemoPerson & { id: string }>,
) {
  const admin = byKey.get('admin')!
  const order: Array<'triaging' | 'contained' | 'resolved' | 'closed'> = [
    'triaging',
    'contained',
    'resolved',
    'closed',
  ]

  for (const template of INCIDENT_TEMPLATES) {
    const incident = await createIncident(db, {
      tenantId,
      locationId: locationIds[template.locationIndex],
      title: template.title,
      summary: template.summary,
      severity: template.severity,
      category: template.category,
      discoveredAt: daysAgo(template.discoveredDaysAgo),
      discoveredBy: admin.id,
      actorId: admin.id,
    })

    // The state machine only allows one step at a time, so walk it. Each step
    // writes its own audit event, which is the point.
    const stopAt = order.indexOf(template.advanceTo as (typeof order)[number])
    for (let step = 0; step <= stopAt; step += 1) {
      await transitionIncident(db, {
        incidentId: incident.id,
        tenantId,
        actorId: admin.id,
        toStatus: order[step],
      })
    }
  }

  return { incidents: INCIDENT_TEMPLATES.length }
}

async function seedProgram(
  db: DB,
  tenantId: string,
  byKey: Map<string, DemoPerson & { id: string }>,
  people: (DemoPerson & { id: string })[],
) {
  const owner = byKey.get('owner')!
  const admin = byKey.get('admin')!

  // ── policies ──
  let published = 0
  for (const template of POLICY_TEMPLATES) {
    const policy = await createPolicy(db, {
      tenantId,
      actorId: admin.id,
      title: template.title,
      bodyMarkdown: template.body,
      version: '1.0',
      effectiveDate: daysAgo(150),
      requiresAcknowledgement: true,
    })

    if (!template.publish) continue

    await publishPolicy(db, { policyId: policy.id, tenantId, actorId: admin.id })
    published += 1

    // Most but not all staff have acknowledged, so the pending count is non-zero.
    // Routed through acknowledgePolicy rather than inserted directly, so each
    // acknowledgement writes its policy.acknowledged audit event like a real
    // one. That costs the backdated acknowledgedAt the domain function does not
    // accept, which is the right trade: the audit trail these screenshots show
    // has to be genuine.
    for (const person of people.slice(0, 3)) {
      await acknowledgePolicy(db, { policyId: policy.id, userId: person.id, tenantId })
    }
  }

  // ── risk register ──
  const assessment = await createRiskAssessment(db, {
    tenantId,
    actorId: admin.id,
    title: `Annual Security Risk Analysis ${now.getFullYear()}`,
  })

  for (const item of RISK_ITEMS) {
    await createRiskItem(db, {
      tenantId,
      actorId: admin.id,
      assessmentId: assessment.id,
      category: item.category,
      description: item.description,
      likelihood: item.likelihood,
      impact: item.impact,
      mitigation: item.mitigation,
      ownerId: admin.id,
      dueAt: daysFromNow(item.dueOffsetDays),
    })
  }

  // ── training ──
  let recordsCompleted = 0
  for (const [courseIndex, courseTemplate] of TRAINING_COURSES.entries()) {
    const course = await createTrainingCourse(db, {
      tenantId,
      actorId: admin.id,
      title: courseTemplate.title,
      description: courseTemplate.description,
      frequencyDays: courseTemplate.frequencyDays,
    })

    for (const [personIndex, person] of people.entries()) {
      // Stagger due dates so the register shows overdue, due-soon, and ok rows.
      const dueOffset = [-9, 6, 40, 120, 200][(personIndex + courseIndex) % 5]

      const record = await assignCourse(db, {
        tenantId,
        actorId: admin.id,
        userId: person.id,
        courseId: course.id,
        dueAt: daysFromNow(dueOffset),
      })

      // Complete roughly half, leaving the rest not-started or overdue.
      if ((personIndex + courseIndex) % 2 !== 0) continue

      await markCompleted(db, {
        recordId: record.id,
        actorId: admin.id,
        actorUserId: admin.id,
        actorCanManageAllUsers: true,
        tenantId,
      })
      recordsCompleted += 1
    }
  }

  // ── vendors ──
  for (const template of VENDOR_TEMPLATES) {
    const vendor = await createVendor(db, {
      tenantId,
      actorId: owner.id,
      name: template.name,
      website: template.website,
      contactEmail: `contracts@${new URL(template.website).hostname}`,
      dataCategories: template.dataCategories,
    })

    if (!template.baa) continue

    await recordBaa(db, {
      vendorId: vendor.id,
      tenantId,
      actorId: owner.id,
      signedAt: daysAgo(template.baa.signedDaysAgo),
      signerName: owner.name,
      signerEmail: owner.email,
      expiresAt: template.baa.expiresInDays === null ? undefined : daysFromNow(template.baa.expiresInDays),
    })
  }

  return { policiesPublished: published, riskItems: RISK_ITEMS.length, trainingCompleted: recordsCompleted }
}

async function seedSoc2(
  db: DB,
  tenantId: string,
  byKey: Map<string, DemoPerson & { id: string }>,
) {
  const admin = byKey.get('admin')!

  await seedSoc2Controls(db)

  for (const controlId of EVIDENCED_CONTROLS) {
    // fileKey must sit under the tenant's evidence prefix or the UI renders it
    // as an invalid artifact.
    const fileKey = `evidence/${tenantId}/soc2/${controlId.toLowerCase().replace('.', '-')}-attestation.pdf`

    await recordManualEvidence(db, {
      tenantId,
      actorId: admin.id,
      controlId,
      fileKey,
      summary: `Signed attestation and supporting export for ${controlId}.`,
    })
  }

  const review = await openAccessReview(db, {
    tenantId,
    actorId: admin.id,
    periodStart: daysAgo(90),
    periodEnd: now,
  })

  return { controlsEvidenced: EVIDENCED_CONTROLS.length, accessReviewId: review.reviewId }
}

// ── entrypoint ──────────────────────────────────────────────────────────────

export type DemoSeedResult = {
  organizationId: string
  organizationName: string
  locationIds: string[]
  people: { key: string; id: string; email: string; name: string; role: DemoRole }[]
  password: string
  counts: Record<string, number>
}

export async function seedDemoWorkspace(db: DB): Promise<DemoSeedResult> {
  faker.seed(FAKER_SEED)

  await resetDemoWorkspace(db)

  const people = await createPeople(db)
  const byKey = new Map(people.map((person) => [person.key, person]))
  const owner = byKey.get('owner')!

  const organization = await createOrganization(db, owner.id)
  await acceptLegalDocuments(db, organization.id, owner)

  const createdLocations = await createLocationsAndMemberships(db, organization.id, people)
  const locationIds = createdLocations.map((location) => location.id)

  // Everything below writes audit events. Running inside an audit context means
  // they carry a real actor rather than an anonymous one.
  const counts = await withAuditContext({ actorId: owner.id }, async () => {
    const taskCounts = await seedTasks(db, organization.id, locationIds, byKey)
    const checklistCounts = await seedChecklists(db, organization.id, locationIds, owner.id)
    const incidentCounts = await seedIncidents(db, organization.id, locationIds, byKey)
    const programCounts = await seedProgram(db, organization.id, byKey, people)
    const soc2Counts = await seedSoc2(db, organization.id, byKey)

    return {
      locations: createdLocations.length,
      members: people.length,
      ...taskCounts,
      ...checklistCounts,
      ...incidentCounts,
      ...programCounts,
      controlsEvidenced: soc2Counts.controlsEvidenced,
    }
  })

  return {
    organizationId: organization.id,
    organizationName: organization.name,
    locationIds,
    people: people.map(({ key, id, email, name, role }) => ({ key, id, email, name, role })),
    password: DEMO_PASSWORD,
    counts,
  }
}

/**
 * `getDb()` returns a lazily-created singleton whose postgres.js pool keeps the
 * event loop alive, so a CLI run has to close it explicitly or the process
 * hangs after the work is done.
 */
async function closeDb(db: DB) {
  const client = (db as unknown as { $client?: { end?: () => Promise<void> } }).$client
  await client?.end?.()
}

async function main() {
  const db = getDb()
  const result = await seedDemoWorkspace(db)

  console.log('')
  console.log(`✓ Demo workspace seeded: ${result.organizationName}`)
  console.log('')
  console.log('  Sign in with any of these (same password):')
  for (const person of result.people) {
    console.log(`    ${person.role.padEnd(17)} ${person.email.padEnd(30)} ${person.name}`)
  }
  console.log(`    password          ${result.password}`)
  console.log('')
  console.log('  Seeded:')
  for (const [key, value] of Object.entries(result.counts)) {
    console.log(`    ${key.padEnd(20)} ${value}`)
  }
  console.log('')

  await closeDb(db)
}

// Only run as a CLI when invoked directly; the screenshot spec imports
// seedDemoWorkspace instead.
const invokedDirectly = process.argv[1]?.replace(/\\/g, '/').endsWith('scripts/demo-seed.ts')
if (invokedDirectly) {
  main().catch((error) => {
    console.error('Demo seed failed:', error)
    process.exit(1)
  })
}
